  p_clRub = L31_clRub;
  p_clGrain = L31_clGrain;
  p_clGrainDepth = L31_clGrainDepth;
  p_clCreases = L31_clCreases;
  p_clCrease = L31_clCrease;
  p_clWear = L31_clWear;
  p_clRough = L31_clRough;
