    k.height = p_clGrainDepth * clPeb * (1.0 - 0.6 * clRubA) - 0.0004 * clCr;
    k.ao = mix(0.85, 1.0, clPeb);
    k.clearcoat = p_clCoat;
    k.clearcoatRough = 0.35;
    k.sheen = mix(p_clColour, vec3(1.0), 0.5) * p_clSheen;
