void look_26(inout Look k) {
  p_clColour = L26_clColour;
  p_clRub = L26_clRub;
  p_clGrain = L26_clGrain;
  p_clGrainDepth = L26_clGrainDepth;
  p_clCreases = L26_clCreases;
  p_clCrease = L26_clCrease;
  p_clWear = L26_clWear;
  p_clRough = L26_clRough;
  p_clRubRough = L26_clRubRough;
  p_clCoat = L26_clCoat;
  p_clSheen = L26_clSheen;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the pebbled grain: cells pressed into the hide, high in their middles, furrowed at their edges
    float clId, clE;
    kvor(uv * p_clGrain + seed, clId, clE);
    float clSee = kfade(2.0 / p_clGrain);
    float clPeb = mix(0.7, smoothstep(0.0, 0.25, clE), clSee);
    float clCell = (kh1(clId) - 0.5) * clSee;
    // the dye's mottle over the hide
    float clMott = kfbm4(uv * 6.0 + seed);
    // soft creases: thin lines wandering every way over the hide where it bends (the contours of a slow noise), each
    // its own strength, some stretches with none
    float clN = kfbm(uv * p_clCreases * 0.3 + seed + 4.0);
    float clCr = (1.0 - smoothstep(0.0, 0.035, abs(clN - 0.5))) * smoothstep(0.4, 0.7, kfbm(uv * 3.0 + seed + 11.0));
    clCr *= p_clCrease * kfade(0.2 / p_clCreases);
    // the rubbing: the hide's own wear in patches, and the kind's hint where it is sat on or gripped
    float clRubA = clamp(p_clWear * smoothstep(0.5, 0.85, kfbm4(uv * 4.0 + seed + 2.0)) + s0.x, 0.0, 1.0);
    vec3 clC = p_clColour * (0.92 + 0.16 * clMott) * (1.0 + 0.035 * clCell);
    clC *= 0.94 + 0.06 * clPeb;
    clC = mix(clC, p_clRub, clRubA * 0.6);
    clC *= 1.0 - 0.18 * clCr;
    k.colour = clC;
    // rubbed smooth: the grain worn flatter and glossier where the hide is rubbed
    k.rough = clamp(mix(p_clRough, p_clRubRough, clRubA) + 0.08 * (1.0 - clPeb), 0.0, 1.0);
    k.height = p_clGrainDepth * clPeb * (1.0 - 0.6 * clRubA) - 0.0004 * clCr;
    k.ao = mix(0.85, 1.0, clPeb);
    k.clearcoat = p_clCoat;
    k.clearcoatRough = 0.35;
    k.sheen = mix(p_clColour, vec3(1.0), 0.5) * p_clSheen;
    k.sheenRough = 0.5;

}

void look_27(inout Look k) {
  p_wcKind = L27_wcKind;
  p_wcColour = L27_wcColour;
  p_wcColour2 = L27_wcColour2;
  p_wcColour3 = L27_wcColour3;
  p_wcRepeat = L27_wcRepeat;
  p_wcLine = L27_wcLine;
  p_wcThread = L27_wcThread;
  p_wcFleck = L27_wcFleck;
  p_wcRelief = L27_wcRelief;
  p_wcSheen = L27_wcSheen;
  p_wcRough = L27_wcRough;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the cloth's own way: x across the stripes, y along them
    vec2 wcG = dot(s3, s3) > 0.25 ? normalize(s3) : vec2(0.0, 1.0);
    vec2 wcUv = vec2(dot(uv, vec2(wcG.y, -wcG.x)), dot(uv, wcG));
    // the twill ground: floats two over and one under, stepping a thread each row, diagonal ribs across it
    vec2 q = wcUv / p_wcThread;
    float row = floor(q.y);
    float over = step(0.34, fract((q.x + row) / 3.0));
    float tw = abs(sin(fract(q.y) * 3.14159)) * mix(0.6, 1.0, over);
    float twF = kfade(p_wcThread * 0.5);
    float h = mix(0.5, tw, twF);
    // the pattern woven through it
    vec3 col = p_wcColour;
    float rep = p_wcRepeat;
    if (p_wcKind < 0.5) {
      // a stripe is drawn while a pixel is no wider than it, its edges softened over the pixel; seen from farther
      // off it is its share of the cloth's colour
      float s = wcBand(wcUv.x, rep, p_wcLine);
      float sMean = p_wcLine / rep;
      s = mix(sMean, s, kfade(p_wcLine * 2.0));
      col = mix(col, p_wcColour2, s);
    } else {
      // two wide bands and one thin line each way in each repeat
      float bu = wcBand(wcUv.x, rep, p_wcLine) + wcBand(wcUv.x + rep * 0.5, rep, p_wcLine * 0.6);
      float bv = wcBand(wcUv.y, rep, p_wcLine) + wcBand(wcUv.y + rep * 0.5, rep, p_wcLine * 0.6);
      float lu = wcBand(wcUv.x + rep * 0.25, rep, p_wcLine * 0.18);
      float lv = wcBand(wcUv.y + rep * 0.25, rep, p_wcLine * 0.18);
      float f = kfade(p_wcLine * 1.2);
      bu = mix(p_wcLine * 1.6 / rep, min(bu, 1.0), f);
      bv = mix(p_wcLine * 1.6 / rep, min(bv, 1.0), f);
      // a band's yarn is the warp's or the weft's, so where only one runs the twill shows half of it
      col = mix(col, p_wcColour2, 0.5 * (bu + bv));
      col = mix(col, p_wcColour3, 0.55 * max(lu, lv) * f);
    }
    // heather: fibres a shade off in the yarn, finer than a thread
    float fleck = smoothstep(0.55, 0.85, kn(uv / (p_wcThread * 0.7) + seed * 3.0));
    col *= 1.0 + p_wcFleck * (mix(0.18, fleck, kfade(p_wcThread * 0.7)) - 0.18) * 1.6;
    col *= 0.94 + 0.1 * kfbm4(uv * 4.0 + seed);
    col *= 0.8 + 0.28 * h;
    k.colour = col;
    k.rough = p_wcRough;
    k.height = p_wcRelief * h;
    k.ao = mix(0.8, 1.0, h);
    k.sheen = mix(col, vec3(1.0), 0.35) * p_wcSheen;
    k.sheenRough = 0.65;

}

void look_28(inout Look k) {
  p_cpColour = L28_cpColour;
  p_cpColour2 = L28_cpColour2;
  p_cpTuft = L28_cpTuft;
  p_cpFleck = L28_cpFleck;
  p_cpCrush = L28_cpCrush;
  p_cpRelief = L28_cpRelief;
  p_cpSheen = L28_cpSheen;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float cpF = kfade(p_cpTuft * 1.5);
    // the tufts' tips: two sizes of noise, the coarse the tufts, the fine the fibres at their tips
    float cpT = kn(uv / p_cpTuft + seed);
    float cpT2 = kn(uv / (p_cpTuft * 0.45) + seed * 3.1);
    float cpTip = mix(0.5, 0.6 * cpT + 0.4 * cpT2, cpF);
    // flecks of the second yarn, a tuft or two across
    float cpFl = mix(0.2, smoothstep(0.62, 0.8, kn(uv / (p_cpTuft * 0.8) + seed * 7.0)), cpF);
    // the pile crushed in soft patches
    float cpCr = kfbm4(uv * 2.5 + seed);
    vec3 cpC = mix(p_cpColour, p_cpColour2, p_cpFleck * cpFl);
    cpC *= (1.0 - p_cpCrush * 0.5) + p_cpCrush * cpCr;
    cpC *= 0.85 + 0.3 * cpTip;
    k.colour = cpC;
    k.rough = 0.97;
    k.height = p_cpRelief * cpTip;
    k.ao = mix(0.8, 1.0, cpTip);
    k.sheen = mix(p_cpColour, vec3(1.0), 0.35) * p_cpSheen;
    k.sheenRough = 0.6;

}

void look_29(inout Look k) {
  p_upKind = L29_upKind;
  p_upColour = L29_upColour;
  p_upColour2 = L29_upColour2;
  p_upThread = L29_upThread;
  p_upFleck = L29_upFleck;
  p_upPrint = L29_upPrint;
  p_upMotif = L29_upMotif;
  p_upRelief = L29_upRelief;
  p_upSheen = L29_upSheen;
  p_upRough = L29_upRough;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // a loop's or a thread's own detail (its ring, its crossing) is half of it across: faded out before it aliases
    float upF = kfade(p_upThread * 0.5);
    vec2 cl = upCloth(uv, p_upKind, p_upThread, seed);
    float h = mix(0.5, cl.x, upF);
    float lite = mix(0.5, cl.y, upF);
    // heather: fibres of the second colour twisted into the yarn, finer than a thread
    float fleck = smoothstep(0.55, 0.85, kn(uv / (p_upThread * 0.7) + seed * 3.0));
    float fleckMean = 0.18;
    float heather = p_upFleck * mix(fleckMean, fleck, kfade(p_upThread * 0.7));
    vec3 col = mix(p_upColour, p_upColour2, heather);
    // the dye's slow unevenness over the cloth
    col *= 0.94 + 0.1 * kfbm4(uv * 4.0 + seed);
    // the print: leaves in the second colour, then the weave over it
    float leaf = upLeaf(uv, p_upMotif, seed) * kfade(p_upMotif * 0.2);
    float leafMean = 0.12;
    col = mix(col, p_upColour2, p_upPrint * mix(leafMean, leaf, kfade(p_upMotif * 0.2)));
    // low places in shadow of the yarn round them, high places catch the light; a mesh's holes dark
    // (a loop pile, bouclé or terry, is soft: its loops shade one another only a little)
    bool upLoops = (p_upKind > 1.5 && p_upKind < 2.5) || (p_upKind > 3.5 && p_upKind < 4.5);
    float shade = p_upKind > 2.5 && p_upKind < 3.5 ? mix(0.25, 1.0, h) : upLoops ? 0.88 + 0.15 * h : 0.78 + 0.3 * h;
    col *= shade * (upLoops ? 0.95 + 0.07 * lite : 0.92 + 0.12 * lite);
    // a loop pile's yarn bunches: clumps of loops a few loops across, standing proud or sinking, seen from across a room
    float clump = upLoops ? kfbm4(uv / (p_upThread * 3.0) + seed) : 0.5;
    float clumpF = kfade(p_upThread * 1.5);
    clump = mix(0.5, clump, clumpF);
    col *= 0.86 + 0.28 * clump;
    h = mix(h, clump, upLoops ? 0.6 : 0.0);
    k.colour = col;
    k.rough = p_upRough;
    k.height = p_upRelief * h;
    k.ao = mix(0.75, 1.0, h);
    k.sheen = mix(p_upColour, vec3(1.0), 0.35) * p_upSheen;
    k.sheenRough = 0.7;

}

void look_30(inout Look k) {
  p_clColour = L30_clColour;
  p_clRub = L30_clRub;
  p_clGrain = L30_clGrain;
  p_clGrainDepth = L30_clGrainDepth;
  p_clCreases = L30_clCreases;
  p_clCrease = L30_clCrease;
  p_clWear = L30_clWear;
  p_clRough = L30_clRough;
  p_clRubRough = L30_clRubRough;
  p_clCoat = L30_clCoat;
  p_clSheen = L30_clSheen;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the pebbled grain: cells pressed into the hide, high in their middles, furrowed at their edges
    float clId, clE;
    kvor(uv * p_clGrain + seed, clId, clE);
    float clSee = kfade(2.0 / p_clGrain);
    float clPeb = mix(0.7, smoothstep(0.0, 0.25, clE), clSee);
    float clCell = (kh1(clId) - 0.5) * clSee;
    // the dye's mottle over the hide
    float clMott = kfbm4(uv * 6.0 + seed);
    // soft creases: thin lines wandering every way over the hide where it bends (the contours of a slow noise), each
    // its own strength, some stretches with none
    float clN = kfbm(uv * p_clCreases * 0.3 + seed + 4.0);
    float clCr = (1.0 - smoothstep(0.0, 0.035, abs(clN - 0.5))) * smoothstep(0.4, 0.7, kfbm(uv * 3.0 + seed + 11.0));
    clCr *= p_clCrease * kfade(0.2 / p_clCreases);
    // the rubbing: the hide's own wear in patches, and the kind's hint where it is sat on or gripped
    float clRubA = clamp(p_clWear * smoothstep(0.5, 0.85, kfbm4(uv * 4.0 + seed + 2.0)) + s0.x, 0.0, 1.0);
    vec3 clC = p_clColour * (0.92 + 0.16 * clMott) * (1.0 + 0.035 * clCell);
    clC *= 0.94 + 0.06 * clPeb;
    clC = mix(clC, p_clRub, clRubA * 0.6);
    clC *= 1.0 - 0.18 * clCr;
    k.colour = clC;
    // rubbed smooth: the grain worn flatter and glossier where the hide is rubbed
    k.rough = clamp(mix(p_clRough, p_clRubRough, clRubA) + 0.08 * (1.0 - clPeb), 0.0, 1.0);
    k.height = p_clGrainDepth * clPeb * (1.0 - 0.6 * clRubA) - 0.0004 * clCr;
    k.ao = mix(0.85, 1.0, clPeb);
    k.clearcoat = p_clCoat;
    k.clearcoatRough = 0.35;
    k.sheen = mix(p_clColour, vec3(1.0), 0.5) * p_clSheen;
    k.sheenRough = 0.5;

}

